describe('Payment Flow - Invalid Card Number', () => {
    beforeEach(() => {
        cy.visit('/payment'); // Adjust the URL to your payment page
    });

    it('should display an error message for an invalid card number', () => {
        cy.get('input[name="cardNumber"]').type('1234 5678 9012 3456'); // Example of an invalid card number
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'Invalid card number');
    });

    it('should not display an error message for a valid card number', () => {
        cy.get('input[name="cardNumber"]').type('4111 1111 1111 1111'); // Example of a valid card number
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('not.exist');
    });
});
